export function decodeLogoLite(u8){const dv=new DataView(u8.buffer,u8.byteOffset,u8.byteLength);if(u8[0]!==82||u8[1]!==71||u8[2]!==76||u8[3]!==49)throw new Error("not an RGL1 file");const jl=dv.getUint32(4,!0),head=JSON.parse(new TextDecoder().decode(u8.subarray(8,8+jl))),base=8+jl,unshuffle=(off,count)=>{const o=new Uint16Array(count),a=u8.subarray(off,off+count),b=u8.subarray(off+count,off+2*count);for(let i=0;i<count;i++)o[i]=a[i]|b[i]<<8;return o},parts=[];for(const p of head.parts){const V=p.V,I=p.I,pos=new Float32Array(V*3),nrm=new Float32Array(V*3),idx=new Uint16Array(I),D=unshuffle(base+p.pos,V*3),prev=[0,0,0];for(let v=0;v<V;v++)for(let k=0;k<3;k++){const z=D[v*3+k],d=z>>1^-(z&1);prev[k]=prev[k]+d&65535,pos[v*3+k]=p.min[k]+prev[k]*(p.max[k]-p.min[k])/65535}const O=unshuffle(base+p.nrm,V*2);for(let v=0;v<V;v++){let u=O[v*2]/65535*2-1,w=O[v*2+1]/65535*2-1,z=1-Math.abs(u)-Math.abs(w),x=u,y=w;z<0&&(x=(1-Math.abs(w))*(u>=0?1:-1),y=(1-Math.abs(u))*(w>=0?1:-1));const l=Math.sqrt(x*x+y*y+z*z)||1;nrm[v*3]=x/l,nrm[v*3+1]=y/l,nrm[v*3+2]=z/l}const C=unshuffle(base+p.idx,I);let hw=0;for(let i=0;i<I;i++){const c=C[i];c===0?idx[i]=hw++:idx[i]=hw-c}parts.push({name:p.name,position:pos,normal:nrm,index:idx})}return{revision:head.revision,source:head.source,parts}}export async function fetchLogoLite(url){if(typeof DecompressionStream!="function")throw new Error("no DecompressionStream");const r=await fetch(url);if(!r.ok||!r.body)throw new Error("logo copy "+r.status);const buf=await new Response(r.body.pipeThrough(new DecompressionStream("gzip"))).arrayBuffer();return decodeLogoLite(new Uint8Array(buf))}